import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE.CqV_9m8U.png",E="/newx-doc/assets/%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1.Dl_15SoP.png",p="/newx-doc/assets/%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE%E7%9A%84%E5%AE%9E%E7%8E%B0.CPhXo-d9.png",l="/newx-doc/assets/%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%AE%9E%E7%8E%B0.fwteUMN5.png",t="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1.8G6QsJKN.png",i="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1%E5%90%8E.B7bnebtQ.png",r="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%90%91%E5%89%8D%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%AE%9E%E7%8E%B0.BB8jUSM9.png",n="/newx-doc/assets/%E5%A4%84%E7%90%86%E5%8A%A0%E7%AD%BE%E7%9A%84%E7%88%B6%E4%BB%BB%E5%8A%A1.DKaxsTfS.png",m="/newx-doc/assets/%E5%90%91%E5%90%8E%E5%8A%A0%E7%AD%BE.vg1wJ3dh.png",A="/newx-doc/assets/%E5%90%91%E5%90%8E%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1.DVDrI-n1.png",u="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%90%91%E5%90%8E%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%AE%9E%E7%8E%B0.DlomkuBg.png",B="/newx-doc/assets/%E5%90%91%E5%90%8E%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%AE%9E%E7%8E%B0.D0vYP6z0.png",h="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%BD%93%E5%89%8D%E4%BB%BB%E5%8A%A1.DWhnzI0m.png",_="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%BD%93%E5%89%8D%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%AE%9E%E7%8E%B0.-v5bzZn1.png",b="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%BD%93%E5%89%8D%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%AE%9E%E7%8E%B02.D0G9oS9k.png",g="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%90%91%E5%90%8E%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1.BZU_-SK7.png",D="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E5%90%91%E5%90%8E%E5%8A%A0%E7%AD%BE%E5%AD%90%E4%BB%BB%E5%8A%A1%E7%9A%84%E5%85%B7%E4%BD%93%E5%AE%9E%E7%8E%B0.BO0s-EPx.png",k="/newx-doc/assets/%E5%87%8F%E7%AD%BE%E5%88%97%E8%A1%A8.3jyFZ1Cq.png",x="/newx-doc/assets/%E5%87%8F%E7%AD%BE%E7%BB%93%E6%9E%9C.CcKn5cM5.png",q="/newx-doc/assets/%E8%8E%B7%E5%BE%97%E5%87%8F%E7%AD%BE%E4%BB%BB%E5%8A%A1%E5%88%97%E8%A1%A8%E7%9A%84%E5%AE%9E%E7%8E%B0.yI_zXoNo.png",P="/newx-doc/assets/%E5%87%8F%E7%AD%BE%E6%93%8D%E4%BD%9C%E7%9A%84%E5%AE%9E%E7%8E%B0.BOTBvG4B.png",z=JSON.parse('{"title":"审批加签、减签","description":"","frontmatter":{},"headers":[],"relativePath":"bpm/sign.md","filePath":"bpm/sign.md","lastUpdated":null}'),y={name:"bpm/sign.md"};function T(f,e,w,N,S,C){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="审批加签、减签" tabindex="-1">审批加签、减签 <a class="header-anchor" href="#审批加签、减签" aria-label="Permalink to &quot;审批加签、减签&quot;">​</a></h1><p>本文，我们来讲解下审批加签、减签的功能：</p><ul><li>加签：添加其他审批人来共同审批，自己仍需参与审批。例如，不好判断当前审批时，可以添加其他人来共同审批</li><li>减签：当以“加签”的方式添加了其他审批人时，可以操作减签进行移除，对方无需再审批。例如，加签有误时，可以通过减签来操作</li></ul><p>其中，加签分成两种：</p><ul><li>向前加签：在任务 A 之【前】添加 B、C、D 三个子任务，在 B、C、D 子任务都审批完成后，任务 A 才能继续审批</li><li>向后加签：在任务 A 之【后】添加 B、C、D 三个子任务，在任务 A 审批通过（处于审批通过中），只有 B、C、D 三个子任务都审批通过，任务 A 才会审批通过</li></ul><h2 id="_1-向前加签" tabindex="-1">1. 向前加签 <a class="header-anchor" href="#_1-向前加签" aria-label="Permalink to &quot;1. 向前加签&quot;">​</a></h2><h3 id="_1-1-发起向前加签" tabindex="-1">1.1 发起向前加签 <a class="header-anchor" href="#_1-1-发起向前加签" aria-label="Permalink to &quot;1.1 发起向前加签&quot;">​</a></h3><h4 id="_1-1-1-操作步骤" tabindex="-1">1.1.1 操作步骤 <a class="header-anchor" href="#_1-1-1-操作步骤" aria-label="Permalink to &quot;1.1.1 操作步骤&quot;">​</a></h4><p>① 首先，点击「加签」按钮，选择被加签的处理人，之后点击「向前加签」按钮，完成向前加签操作。如下图所示：</p><p><img src="'+s+'" alt="向前加签"></p><p>② 之后，可以看到当前任务变成“待审核”状态，它有加签出来的一个子任务，该子任务的状态是“待审核”状态，如下图所示：</p><p><img src="'+E+'" alt="向前加签子任务"></p><h4 id="_1-1-2-后端实现" tabindex="-1">1.1.2 后端实现 <a class="header-anchor" href="#_1-1-2-后端实现" aria-label="Permalink to &quot;1.1.2 后端实现&quot;">​</a></h4><p>对应 BpmTaskController 的 <code>#createSignTask(...)</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+p+'" alt="向前加签的实现"></p><ul><li>红圈 ① 的 <code>2.2</code> 处：需要将当前任务的 <code>assignee</code> 置空，并保存到 <code>owner</code> 中，避免它被审批。因为它如何被审批，就会直接进入下一个节点，而不会等待加签的子任务审批完成，显然这不是我们所希望的</li><li>红圈 ② 的 <code>2.4</code> 处：通过 <code>scopeType</code> 标记当前任务是向前还是向后加签，因为一个任务不能同时向前和向后加签。这里，我们将 <code>scopeType</code> 设置为 <code>before</code>，表示向前加签</li><li>红圈 ③ 的 <code>2.6</code> 处：更新当前任务的状态为 <code>WAITING</code>，表示当前任务处于“待审核状态”</li><li>红圈 ④ 的 <code>3.</code> 处：调用 <code>#createSignTaskList(...)</code> 方法，创建加签的子任务，如下图所示：</li></ul><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+l+'" alt="向前加签子任务的实现"></p><ul><li>红圈 ⑤ 的 <code>1</code> 处：创建加签的子任务，将当前任务的属性部分复制给改子任务</li><li>红圈 ⑥ 的 <code>2.1</code> 处：设置向前加签的子任务的 <code>assignee</code> 审批人</li><li>红圈 ⑦ 的 <code>2.3</code> 处：真正保存加签的子任务</li></ul><h3 id="_1-2-审批向前加签子任务" tabindex="-1">1.2 审批向前加签子任务 <a class="header-anchor" href="#_1-2-审批向前加签子任务" aria-label="Permalink to &quot;1.2 审批向前加签子任务&quot;">​</a></h3><h4 id="_1-2-1-操作步骤" tabindex="-1">1.2.1 操作步骤 <a class="header-anchor" href="#_1-2-1-操作步骤" aria-label="Permalink to &quot;1.2.1 操作步骤&quot;">​</a></h4><p>登录账号 test、密码 test123 的用户，审批加签任务。</p><p>① 和普通审批一样，点击【通过】按钮，将子任务审批通过，如下图所示：</p><p><img src="'+t+'" alt="审批向前加签子任务"></p><p>② 之后，可以看到当前（原）任务又变回“待审核”状态，加签出来的子任务处于“审核通过”状态，如下图所示：</p><p><img src="'+i+'" alt="审批向前加签子任务后"></p><p>后续，我们登录回之前的账号，继续审批当前（原）任务即可。</p><h4 id="_1-2-2-后端实现" tabindex="-1">1.2.2 后端实现 <a class="header-anchor" href="#_1-2-2-后端实现" aria-label="Permalink to &quot;1.2.2 后端实现&quot;">​</a></h4><p>因为和普通审批一样，所以对应的还是 BpmTaskController 的 <code>#approveTask(...)</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+r+'" alt="审批向前加签子任务的实现"></p><p>关键还是 <code>#handleParentTaskIfSign(...)</code> 方法，在向前加签的情况下，需要将当前（原）任务又变回“待审核”状态。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+n+'" alt="处理加签的父任务"></p><ul><li>红圈 ① 的 <code>1.1</code> 处：由于可以加签多个子任务，所以需要全部审批通过后才能继续审批当前（原）任务</li><li>红圈 ② 的 <code>2.</code> 处：清空当前（原）任务的 <code>scopeType</code> 属性，表示当前任务不再处于加签状态，这样它后续可以自由的向前或是向后继续加签</li><li>红圈 ③ 的 <code>3.1</code> 处：恢复当前（原）任务的 <code>assignee</code> 审批人，并更新状态回 <code>RUNNING</code> 审批中</li><li>红圈 ④ 的 <code>4.</code> 处：由于加签出来的子任务，自身可以继续被加签，所以需要递归向上处理。如果要体验一下，就在「1.2.1 操作步骤」时，不要审批通过，而是加签</li></ul><h2 id="_2-向后加签" tabindex="-1">2. 向后加签 <a class="header-anchor" href="#_2-向后加签" aria-label="Permalink to &quot;2. 向后加签&quot;">​</a></h2><h3 id="_2-1-发起向后加签" tabindex="-1">2.1 发起向后加签 <a class="header-anchor" href="#_2-1-发起向后加签" aria-label="Permalink to &quot;2.1 发起向后加签&quot;">​</a></h3><h4 id="_2-1-1-操作步骤" tabindex="-1">2.1.1 操作步骤 <a class="header-anchor" href="#_2-1-1-操作步骤" aria-label="Permalink to &quot;2.1.1 操作步骤&quot;">​</a></h4><p>① 首先，点击「加签」按钮，选择被加签的处理人，之后点击「向后加签」按钮，完成向后加签操作。如下图所示：</p><p><img src="'+m+'" alt="向后加签"></p><p>② 之后，可以看到当前任务变成“审核中”状态，它有加签出来的一个子任务，该子任务的状态是“待审核”状态，如下图所示：</p><p><img src="'+A+'" alt="向后加签子任务"></p><h3 id="_2-2-审批向后加签子任务" tabindex="-1">2.2 审批向后加签子任务 <a class="header-anchor" href="#_2-2-审批向后加签子任务" aria-label="Permalink to &quot;2.2 审批向后加签子任务&quot;">​</a></h3><p>对应 BpmTaskController 的 <code>#createSignTask(...)</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+u+'" alt="审批向后加签子任务的实现"></p><ul><li>相比于向前加签，向后加签的实现更加简单，因为它不需要处理当前（原）任务的状态，只需要创建加签的子任务即可</li></ul><p>调用 <code>#createSignTaskList(...)</code> 方法，创建加签的子任务，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+B+'" alt="向后加签子任务的实现"></p><ul><li>红圈 ① 的 <code>1</code> 处：创建的向后加签的子任务，只将 <code>owner</code> 设置为选择加签的处理人，不包括 <code>assignee</code> 审批人。原因是，需要等到当前（原）任务审批通过后，才会设置 <code>assignee</code> 审批人</li><li>红圈 ② 的 <code>2.</code> 处：设置向后加签的子任务的状态为 <code>WAITING</code> 待审核状态。原因是，当前（原）任务审批通过后，才会设置子任务为 <code>RUNNING</code> 审批中</li></ul><h3 id="_2-2-审批当前-原-任务" tabindex="-1">2.2 审批当前（原）任务 <a class="header-anchor" href="#_2-2-审批当前-原-任务" aria-label="Permalink to &quot;2.2 审批当前（原）任务&quot;">​</a></h3><h3 id="_2-2-1-操作步骤" tabindex="-1">2.2.1 操作步骤 <a class="header-anchor" href="#_2-2-1-操作步骤" aria-label="Permalink to &quot;2.2.1 操作步骤&quot;">​</a></h3><p>不用切换账号！直接审批当前（原）任务即可。</p><p>点击【通过】按钮，将当前（原）任务审批通过，如下图所示：</p><p><img src="'+h+'" alt="审批当前任务"></p><p>可以看到当前（原）任务变成 <code>APPROVING</code> “审批通过中”状态，加签出来的子任务变成 <code>RUNNING</code> 审批中状态。</p><h3 id="_2-2-2-后端实现" tabindex="-1">2.2.2 后端实现 <a class="header-anchor" href="#_2-2-2-后端实现" aria-label="Permalink to &quot;2.2.2 后端实现&quot;">​</a></h3><p>对应 BpmTaskController 的 <code>#createSignTask(...)</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+_+'" alt="审批当前任务的实现"></p><p>核心实现在 <code>#approveAfterSignTask(...)</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+b+'" alt="审批当前任务的实现2"></p><ul><li>对于当前（原）任务来说，任务变成 <code>APPROVING</code> “审批通过中”状态</li><li>对于被加签出来的子任务来说，任务变成 <code>RUNNING</code> “审批中”状态，并设置 <code>assignee</code> 审批人。也就是说，被加签的人可以开始审批啦~</li></ul><h3 id="_2-3-审批向后加签子任务" tabindex="-1">2.3 审批向后加签子任务 <a class="header-anchor" href="#_2-3-审批向后加签子任务" aria-label="Permalink to &quot;2.3 审批向后加签子任务&quot;">​</a></h3><h4 id="_2-3-1-操作步骤" tabindex="-1">2.3.1 操作步骤 <a class="header-anchor" href="#_2-3-1-操作步骤" aria-label="Permalink to &quot;2.3.1 操作步骤&quot;">​</a></h4><p>登录账号 test、密码 test123 的用户，审批加签任务。</p><p>点击【通过】按钮，将后向加签的子任务审批通过，如下图所示：</p><p><img src="'+g+'" alt="审批向后加签子任务"></p><p>可以看到当前（原）任务变成 <code>APPROVE</code> “审批通过”状态，加签出来的子任务也变成 <code>APPROVE</code> “审批通过”状态。</p><h4 id="_2-3-2-后端实现" tabindex="-1">2.3.2 后端实现 <a class="header-anchor" href="#_2-3-2-后端实现" aria-label="Permalink to &quot;2.3.2 后端实现&quot;">​</a></h4><p>对应 BpmTaskController 的 <code>#createSignTask(...)</code> 方法，核心实现在 <code>#handleParentTaskIfSign(...)</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+D+'" alt="审批向后加签子任务的具体实现"></p><ul><li>红圈部分，当前（原）任务变成 <code>APPROVE</code> “审批通过”状态，并调用 <code>TaskService#complete(...)</code> 方法来完成</li></ul><p>友情提示：</p><p>向前、向后加签的逻辑，整体可能有点弯弯绕绕~ 大家在理解的时候，可以找个纸头画一画，这样会更加清晰~</p><h2 id="_3-减签" tabindex="-1">3. 减签 <a class="header-anchor" href="#_3-减签" aria-label="Permalink to &quot;3. 减签&quot;">​</a></h2><h3 id="_3-1-操作步骤" tabindex="-1">3.1 操作步骤 <a class="header-anchor" href="#_3-1-操作步骤" aria-label="Permalink to &quot;3.1 操作步骤&quot;">​</a></h3><p>① 点击【减签】按钮，获得可减钱的任务列表，如下图所示：</p><p><img src="'+k+'" alt="减签列表"></p><p>② 选择需要减签的任务，点击【减签】按钮，完成减签操作。如下图所示：</p><p><img src="'+x+'" alt="减签结果"></p><h3 id="_3-2-后端实现" tabindex="-1">3.2 后端实现 <a class="header-anchor" href="#_3-2-后端实现" aria-label="Permalink to &quot;3.2 后端实现&quot;">​</a></h3><p>① 获得可减钱的任务列表，对应 BpmTaskController 的 <code>#getTaskListByParentTaskId(...)</code> 方法。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+q+'" alt="获得减签任务列表的实现"></p><p>② 执行减签操作，对应 BpmTaskController 的 <code>#deleteSignTask(...)</code> 方法。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-bpm-api 和 yudao-module-bpm-biz 子模块，代码直接合并到 yudao-module-bpm 模块的 src 目录下，更适合单体项目</p><p><img src="'+P+'" alt="减签操作的实现"></p><ul><li>红圈 ① 的 <code>2.1</code>、<code>2.2</code> 处：获得所有的子任务列表，一方面更新它们为 <code>CANCEL</code> “已取消”状态，另一方面调用 <code>TaskService#deleteTasks(...)</code> 删除它们</li><li>红圈 ② 的 <code>4.</code> 处：需要调用 <code>#handleParentTaskIfSign(...)</code> 方法，处理当前（原）任务的状态，不然该任务的状态就一直卡在加签的情况下了</li></ul>',93)])])}const G=o(y,[["render",T]]);export{z as __pageData,G as default};
